def main():
    missing = json.loads(MISSING.read_text(encoding="utf-8"))
    missing_keys = list(missing.keys())
    if len(T) < len(missing_keys):
        raise SystemExit(f"Incomplete: {len(T)}/{len(missing_keys)} translated so far")
    out = {k: T[k] for k in missing_keys}
    OUTPUT.write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(out)} entries to {OUTPUT.name}")

if __name__ == "__main__":
    main()
